function validate([target]) {
  if (!Array.isArray(target) || target.length < 1 || target.length > 100000) return 'target needs 1 to 100000 values.';
  if (target.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value must be an integer from 1 to 100000.';
  let answer = target[0];
  for (let i = 1; i < target.length; i++) answer += Math.max(0, target[i] - target[i - 1]);
  if (answer > 2147483647) return 'The answer must fit in a 32-bit signed integer.';
  return null;
}

