function minNumberOperations(target) {
  // Divide and conquer: raise the whole range to its minimum, then solve the pieces between minimum positions.
  const solve = (low, high, base) => {
    if (low > high) return 0;
    let least = Infinity;
    for (let i = low; i <= high; i++) least = Math.min(least, target[i]);
    let total = least - base;
    let start = low;
    for (let i = low; i <= high + 1; i++) {
      if (i === high + 1 || target[i] === least) {
        total += solve(start, i - 1, least);
        start = i + 1;
      }
    }
    return total;
  };
  return solve(0, target.length - 1, 0);
}

