  for (let i = 0; i < n; i++) {
    let value;
    if (shape === 0) value = int(1, top);
    else if (shape === 1) value = i % 2 === 0 ? int(1, Math.max(1, Math.floor(top / 10))) : int(Math.ceil(top / 2), top);
    else if (shape === 2) value = Math.min(top, 1 + Math.floor((i * top) / n));
    else if (shape === 3) value = Math.max(1, top - Math.floor((i * top) / n));
